import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)
    orders_info = {}  # id -> {'side':..,'price':..,'qty':..,'time':..}
    time_counter = 0

    for order in orders:
        time_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in orders_info:
                del orders_info[oid]
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = heapq.heappop(opp_heap)
            if side == 'buy':
                rprice, rtime, rid = top
            else:
                negrprice, rtime, rid = top
                rprice = -negrprice

            # check validity
            if rid not in orders_info or orders_info[rid]['qty'] <= 0:
                continue  # discard stale entry

            resting = orders_info[rid]

            # check price condition
            if typ == 'market':
                condition_ok = True
            else:
                if side == 'buy':
                    condition_ok = rprice <= price
                else:
                    condition_ok = rprice >= price

            if not condition_ok:
                # push back and stop matching
                heapq.heappush(opp_heap, top)
                break

            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                buy_id = oid
                sell_id = rid
            else:
                buy_id = rid
                sell_id = oid

            trades.append([buy_id, sell_id, rprice, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] <= 0:
                del orders_info[rid]
                # do not push back, it's fully filled
            else:
                # push back with same time key
                heapq.heappush(opp_heap, top)

        if typ == 'limit' and remaining > 0:
            orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': time_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, time_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, time_counter, oid))
        # ioc and market: discard remainder

    return trades

